// Space_Invaders/Game.js — the orchestrator.
// Owns: state machine (MENU / PLAYING / PAUSED / WAVE_CLEAR / GAME_OVER), rules,
// scoring + combo multiplier, lives/waves, HUD DOM, and all VFX event dispatch.
// Entities are dumb about presentation; every camera-shake / hit-stop / particle /
// ring / score-text / audio event flows through the tables in plan.md §4.

import * as THREE from 'three';
import { NeonMaterials } from '../shared/materials/NeonMaterials.js';
import { ParticleManager } from '../shared/vfx/ParticleManager.js';
import { CameraShake } from '../shared/vfx/CameraShake.js';
import { HitStop } from '../shared/vfx/HitStop.js';
import { MotionTrails } from '../shared/vfx/MotionTrails.js';
import { ShockwaveRings } from '../shared/vfx/ShockwaveRings.js';
import { FloatingScoreText } from '../shared/vfx/FloatingScoreText.js';
import { AudioEngine } from '../shared/audio/AudioEngine.js';
import { makeGridFloorTexture } from '../shared/utils/proceduralTextures.js';

import { AlienFormation } from './entities/AlienFormation.js';
import { PlayerShip } from './entities/PlayerShip.js';
import { BulletSystem } from './entities/BulletSystem.js';
import { Bunkers } from './entities/Bunkers.js';
import { UfoShip } from './entities/UfoShip.js';
import { TYPE_COLORS, TYPE_SCORES } from './entities/AlienTypes.js';

import {
  WORLD, PLAYER, GRID, ALIEN_RADIUS, FORMATION, SCORING, WAVES, BUNKERS, UFO, VFX, CAMERA,
  waveFireMult, waveAlienBulletSpeed,
} from './config.js';

const STATE = Object.freeze({
  MENU: 'menu', PLAYING: 'playing', PAUSED: 'paused', WAVE_CLEAR: 'wave_clear', GAME_OVER: 'game_over',
});

const HI_SCORE_KEY = 'si_hiscore';
const DEFENSE_Z = WORLD.PLAYER_Z - WORLD.DEFENSE_MARGIN; // invasion line (z = 13)

export class Game {
  /**
   * @param {import('../shared/core/Engine.js').Engine} engine
   * @param {import('../shared/core/InputController.js').InputController} input
   */
  constructor(engine, input) {
    this.engine = engine;
    this.input = input;
    this.scene = engine.scene;
    this.camera = engine.camera;

    // ------------------------------------------------------------- materials --
    this.mats = new NeonMaterials();

    // -------------------------------------------------------------- environment --
    this._buildEnvironment();

    // ---------------------------------------------------------------- entities --
    this.formation = new AlienFormation(this.scene, this.mats);
    this.player = new PlayerShip(this.scene, this.mats);
    this.bullets = new BulletSystem(this.scene, {
      playerGeo: new THREE.BoxGeometry(0.32, 0.32, 1.8),
      playerMat: this.mats.neon(0x66ffff, 4.0),
      alienGeo: new THREE.BoxGeometry(0.5, 1.0, 0.5),
      alienMat: this.mats.neon(0xffb347, 3.2),
    });
    this.bunkers = new Bunkers(this.scene, this.mats.get({ color: 0x16323e, metalness: 0.55, roughness: 0.5 }));
    this.ufo = new UfoShip(this.scene, {
      hull: this.mats.hull(0x274058),
      dome: this.mats.get({ color: 0x9fdcff, metalness: 0.3, roughness: 0.15 }),
      lights: this.mats.neon(0xff4d6d, 3.6),
    });

    // -------------------------------------------------------------------- vfx --
    this.particles = new ParticleManager(this.scene);
    this.shake = new CameraShake(this.camera, { maxAmp: 1.35, decayTau: 0.9, fovKick: 4 });
    this.hitstop = new HitStop(engine);
    this.trails = new MotionTrails(this.scene, { maxTrails: 8, segments: 12 });
    this.rings = new ShockwaveRings(this.scene, { max: 12 });
    this.scoreText = new FloatingScoreText(engine.container, this.camera, { max: 14 });

    // ------------------------------------------------------------------- audio --
    this.audio = new AudioEngine();

    // ------------------------------------------------------------- game state --
    this.state = STATE.MENU;
    this.score = 0;
    this.lives = 3;
    this.wave = 1;
    this.combo = 1;
    this.comboTimer = 0;
    this.nextLifeAt = SCORING.EXTRA_LIFE_EVERY;
    this.hiScore = this._readHiScore();

    this.deathTimer = 0;          // respawn countdown after a hit (sim seconds)
    this.waveClearTimer = 0;     // WAVE_CLEAR state countdown
    this._fireAcc = 0;           // alien fire accumulator (shots)
    this._ufoTimer = UFO.SPAWN_MIN + Math.random() * (UFO.SPAWN_MAX - UFO.SPAWN_MIN);
    this._blinkPhase = 0;        // invulnerability blink clock
    this.flashAlpha = 0;         // impact flash layer opacity

    this._trailPlayerId = null;  // motion-trail slot for the player bullet
    this._off = new THREE.Vector3(); // scratch: camera shake offset

    // --------------------------------------------------------------------- dom --
    this._buildDom();
    this._hudSync(true);

    // ------------------------------------------------------------- engine hooks --
    engine.onFrame(() => {
      this.input.update();           // poll keyboard + gamepad once per frame…
      this._pollEdges();             // …and resolve state transitions before sim steps
    });
    engine.addSimUpdater((dt) => this._simUpdate(dt));
    engine.addRealtimeUpdater((dt) => this._realtimeUpdate(dt));

    // -------------------------------------------------- disposal (reverse order) --
    engine.registerDisposer(() => this.audio.dispose());
    engine.registerDisposer(() => this.input.dispose());
    engine.registerDisposer(() => this.scoreText.dispose());
    engine.registerDisposer(() => this.rings.dispose());
    engine.registerDisposer(() => this.trails.dispose());
    engine.registerDisposer(() => this.particles.dispose());
    engine.registerDisposer(() => this.ufo.dispose());
    engine.registerDisposer(() => this.bunkers.dispose());
    engine.registerDisposer(() => this.bullets.dispose());
    engine.registerDisposer(() => this.player.dispose());
    engine.registerDisposer(() => this.formation.dispose());
    engine.registerDisposer(() => {
      for (const g of this._envGeos) g.dispose();
      for (const m of this._envMats) m.dispose();
      if (this._floorTex) this._floorTex.dispose();
    });
    engine.registerDisposer(() => this.mats.disposeAll());

    // Menu attract mode: the swarm idles behind the title screen.
    this.player.group.visible = false;
  }

  // ================================================================ environment

  _buildEnvironment() {
    const scene = this.scene;
    this._envGeos = [];
    this._envMats = [];

    // --- neon corridor floor (procedural grid texture, zero image files) -------
    this._floorTex = makeGridFloorTexture(1024);
    const floorMat = new THREE.MeshStandardMaterial({
      color: 0xffffff, map: this._floorTex,
      emissiveMap: this._floorTex, emissive: 0x19c8e6, emissiveIntensity: 1.15,
      metalness: 0.45, roughness: 0.62,
    });
    const floorGeo = new THREE.PlaneGeometry(150, 95);
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    scene.add(floor);
    this._envGeos.push(floorGeo);
    this._envMats.push(floorMat);

    // --- invasion line: the magenta bar aliens must not cross -------------------
    const lineGeo = new THREE.BoxGeometry(44, 0.16, 0.5);
    const lineMat = this.mats.neon(0xff2bd6, 2.3);
    const line = new THREE.Mesh(lineGeo, lineMat);
    line.position.set(0, 0.1, DEFENSE_Z);
    scene.add(line);
    this._envGeos.push(lineGeo);

    // --- corridor edge light strips ---------------------------------------------
    const stripGeo = new THREE.BoxGeometry(0.35, 0.35, 42);
    const stripMat = this.mats.neon(0x00f5ff, 1.9);
    for (const sx of [-1, 1]) {
      const strip = new THREE.Mesh(stripGeo, stripMat);
      strip.position.set(sx * 21.5, 0.3, -1);
      scene.add(strip);
    }
    this._envGeos.push(stripGeo);

    // --- lighting rig (plan §3.2) -------------------------------------------------
    const ambient = new THREE.AmbientLight(0x2a3550, 0.6);
    const key = new THREE.DirectionalLight(0xbfd4ff, 1.1);
    key.position.set(8, 20, 24);
    const rimMagenta = new THREE.PointLight(0xff2bd6, 260, 95, 2);
    rimMagenta.position.set(-18, 7, -14);
    const rimCyan = new THREE.PointLight(0x00f5ff, 260, 95, 2);
    rimCyan.position.set(18, 7, -14);
    scene.add(ambient, key, rimMagenta, rimCyan);
    this._envLights = [ambient, key, rimMagenta, rimCyan];
  }

  // ======================================================================= dom

  _el(tag, cls, html) {
    const el = document.createElement(tag);
    if (cls) el.className = cls;
    if (html !== undefined) el.innerHTML = html;
    return el;
  }

  _buildDom() {
    const root = this.engine.container;

    // Impact flash layer (style.css defines #impact-flash).
    this._flashEl = this._el('div');
    this._flashEl.id = 'impact-flash';
    root.appendChild(this._flashEl);

    // HUD.
    const hud = document.getElementById('hud') || (() => { const h = this._el('div'); h.id = 'hud'; root.appendChild(h); return h; })();
    const top = this._el('div', 'hud-top');

    const left = this._el('div', 'glass-panel hud-left');
    left.appendChild(this._el('div', 'hud-label', 'Score'));
    this._scoreEl = this._el('div', 'hud-score', '0');
    left.appendChild(this._scoreEl);
    this._hiEl = this._el('div', 'hud-hiscore', `HI ${this.hiScore}`);
    left.appendChild(this._hiEl);

    const multPanel = this._el('div', 'glass-panel hud-mult');
    const multRow = this._el('div', 'mult-row');
    this._multValEl = this._el('span', 'mult-value', '×1');
    const bar = this._el('div', 'mult-bar');
    this._multFillEl = this._el('div', 'mult-fill');
    bar.appendChild(this._multFillEl);
    multRow.appendChild(this._multValEl);
    multRow.appendChild(bar);
    multPanel.appendChild(multRow);
    left.appendChild(multPanel);

    const right = this._el('div', 'glass-panel hud-right');
    right.appendChild(this._el('div', 'hud-label', 'Wave'));
    this._waveEl = this._el('div', 'hud-wave', '1');
    right.appendChild(this._waveEl);
    this._livesEl = this._el('div', 'hud-lives');
    right.appendChild(this._livesEl);

    top.appendChild(left);
    top.appendChild(right);
    hud.appendChild(top);

    // Overlays.
    const mkOverlay = (titleHtml, bodyFn) => {
      const ov = this._el('div', 'overlay hidden');
      const dlg = this._el('div', 'glass-panel dialog');
      if (titleHtml) dlg.appendChild(titleHtml);
      bodyFn(dlg);
      ov.appendChild(dlg);
      root.appendChild(ov);
      return ov;
    };

    this._menuOv = mkOverlay(this._el('h1', 'game-title', 'SPACE INVADERS'), (dlg) => {
      dlg.appendChild(this._el('div', 'game-subtitle', 'Neon Corridor // 1978 Reimagined'));
      const grid = this._el('div', 'controls-grid');
      for (const [k, v] of [['A / D · ← →', 'Move'], ['SPACE · A-Button', 'Fire'], ['P / ESC', 'Pause']]) {
        grid.appendChild(this._el('span', 'key', k));
        grid.appendChild(this._el('span', null, v));
      }
      dlg.appendChild(grid);
      dlg.appendChild(this._el('div', 'press-start', 'Press Start'));
      dlg.appendChild(this._el('div', 'hint-line', 'Keyboard + Gamepad · 100% Procedural · WebAudio Synth'));
    });

    this._pauseOv = mkOverlay(this._el('h2', null, 'PAUSED'), (dlg) => {
      dlg.appendChild(this._el('div', 'press-start', 'Press P to Resume'));
    });

    this._overOv = mkOverlay(this._el('h2', null, 'INVADED'), (dlg) => {
      this._finalScoreEl = this._el('div', 'big-number', '0');
      dlg.appendChild(this._finalScoreEl);
      this._finalHiEl = this._el('div', 'hud-hiscore', '');
      dlg.appendChild(this._finalHiEl);
      dlg.appendChild(this._el('div', 'press-start', 'Press Start'));
    });
  }

  _setState(s) {
    this.state = s;
    const show = (ov, on) => ov.classList.toggle('hidden', !on);
    show(this._menuOv, s === STATE.MENU);
    show(this._pauseOv, s === STATE.PAUSED);
    show(this._overOv, s === STATE.GAME_OVER);

    if (s === STATE.PLAYING) {
      this.audio.setAliveRatio(this.formation.aliveRatio);
    } else if (s !== STATE.MENU) {
      this.audio.stopMarch();
    }
  }

  // ===================================================================== input

  _pollEdges() {
    const inp = this.input;

    if (inp.consumeEdge('pause')) {
      if (this.state === STATE.PLAYING) { this._setState(STATE.PAUSED); this.audio.uiBlip(440); }
      else if (this.state === STATE.PAUSED) { this._setState(STATE.PLAYING); this.audio.uiBlip(660); }
    }

    // Start / fire edges only mean "start" outside of active play.
    const wantsStart = inp.consumeEdge('start') || (this.state !== STATE.PLAYING && inp.consumeEdge('fire'));
    if (!wantsStart) return;

    if (this.state === STATE.MENU || this.state === STATE.GAME_OVER) {
      this.audio.uiBlip(880);
      this.startGame();
    } else if (this.state === STATE.PAUSED) {
      this._setState(STATE.PLAYING);
    }
  }

  // ==================================================================== states

  startGame() {
    this.score = 0;
    this.lives = 3;
    this.wave = 1;
    this.combo = 1;
    this.comboTimer = 0;
    this.nextLifeAt = SCORING.EXTRA_LIFE_EVERY;
    this.deathTimer = 0;
    this._fireAcc = 0;
    this._ufoTimer = UFO.SPAWN_MIN + Math.random() * (UFO.SPAWN_MAX - UFO.SPAWN_MIN);

    this.formation.reset(1);
    this.bunkers.rebuild();
    this.bullets.clearAll();
    this.ufo.deactivate();
    this.audio.ufoStop();
    this.trails.clear();
    this.rings.clear();
    this.scoreText.clear();
    this.player.respawn();
    this.player.group.visible = true;

    this._setState(STATE.PLAYING);
    this._hudSync(true);
  }

  _waveClear() {
    this.audio.waveClear();
    this.hitstop.trigger(VFX.HITSTOP_WAVE_CLEAR_MS, VFX.HITSTOP_WAVE_CLEAR_SCALE);
    this.shake.add(VFX.SHAKE_WAVE_CLEAR);
    // Celebratory ring at the swarm's centroid.
    this.rings.spawn(0, GRID.Y_BASE, -12, { color: 0x66ffff, maxScale: 9, life: 0.8, orient: 'billboard' });
    this.particles.burst(0, GRID.Y_BASE + 1, -12, 40, { color: 0x66ffff, speed: 10, priority: VFX.PR_ALIEN_KILL, upBias: 0.7 });

    this.waveClearTimer = 2.2;
    this._setState(STATE.WAVE_CLEAR);
  }

  _waveClearTick(dt) {
    this.waveClearTimer -= dt;
    if (this.waveClearTimer > 0) return;

    // Advance to the next wave.
    this.wave++;
    this.combo = 1;
    this.comboTimer = 0;
    this._fireAcc = 0;
    this._ufoTimer = UFO.SPAWN_MIN + Math.random() * (UFO.SPAWN_MAX - UFO.SPAWN_MIN);

    this.formation.reset(this.wave);
    this.bunkers.rebuild();
    this.bullets.clearAll();
    this.ufo.deactivate();
    this.audio.ufoStop();
    this.trails.clear();
    this.player.respawn();

    this.scoreText.spawn(0, 7.5, -12, `WAVE ${this.wave}`, '#ff2bd6');
    this._setState(STATE.PLAYING);
    this._hudSync(true);
  }

  _gameOver(reason) {
    void reason;
    if (this.score > this.hiScore) {
      this.hiScore = this.score;
      try { localStorage.setItem(HI_SCORE_KEY, String(this.hiScore)); } catch { /* storage blocked */ }
    }
    this.audio.stopMarch();
    this.audio.gameOver();
    this._finalScoreEl.textContent = String(this.score);
    const newHi = this.score >= this.hiScore && this.score > 0;
    this._finalHiEl.textContent = newHi ? `NEW HI-SCORE ${this.hiScore}` : `HI-SCORE ${this.hiScore}`;
    this._setState(STATE.GAME_OVER);
  }

  _readHiScore() {
    try { return Math.max(0, parseInt(localStorage.getItem(HI_SCORE_KEY) || '0', 10) || 0); } catch { return 0; }
  }

  // ================================================================== sim loop

  _simUpdate(dt) {
    switch (this.state) {
      case STATE.MENU: this._ambient(dt); break;
      case STATE.PLAYING: this._updatePlaying(dt); break;
      case STATE.WAVE_CLEAR: this._waveClearTick(dt); break;
      default: break; // PAUSED / GAME_OVER — world frozen, VFX keep breathing
    }
  }

  /** Attract mode behind the title screen. */
  _ambient(dt) {
    this.formation.update(dt, 1);
  }

  _updatePlaying(dt) {
    const p = this.player;

    // ---- player ---------------------------------------------------------------
    if (p.alive) {
      const ax = Math.max(-1, Math.min(1, this.input.axes.x));
      p.update(dt, ax, PLAYER.SPEED);

      // Invulnerability blink (deterministic sim clock).
      if (p.isInvulnerable()) {
        this._blinkPhase += dt;
        p.group.visible = Math.floor(this._blinkPhase / 0.1) % 2 === 0;
      } else {
        p.group.visible = true;
      }

      // Fire — held input, cooldown-gated (classic single live bullet enforced in BulletSystem).
      if (this.input.fire && p.canFire()) {
        const m = p.consumeShot(PLAYER.FIRE_COOLDOWN);
        if (this.bullets.firePlayer(m.x, m.z)) {
          this.audio.shoot();
          if (this._trailPlayerId === null) this._trailPlayerId = this.trails.acquire(0x66ffff, 0.14);
        }
      }
    } else if (!p.alive && this.deathTimer <= 0 && !this._pendingGameOver) {
      // Countdown itself runs in real-time (_realtimeUpdate); respawn when it expires.
      p.respawn();
    }

    // ---- bullets ---------------------------------------------------------------
    const bres = this.bullets.update(dt);
    if (bres.player && this._trailPlayerId !== null) {
      this.trails.push(this._trailPlayerId, bres.player.x, PLAYER.Y + 1.0, bres.player.z);
    }
    for (const b of bres.aliens) {
      if (b.trail !== undefined && b.trail !== null) this.trails.push(b.trail, b.x, 1.0, b.z);
    }

    // ---- formation -------------------------------------------------------------
    const { steppedDown } = this.formation.update(dt, this.wave);
    if (steppedDown) this.shake.add(0.04); // the swarm "thuds" on each wall bounce

    // ---- alien fire ------------------------------------------------------------
    this._alienFireTick(dt);

    // ---- ufo --------------------------------------------------------------------
    this._ufoTick(dt);

    // ---- collisions --------------------------------------------------------------
    this._collisions(bres);

    // ---- combo decay ---------------------------------------------------------------
    if (this.comboTimer > 0) {
      this.comboTimer -= dt;
      if (this.comboTimer <= 0 && this.combo !== 1) {
        this.combo = 1;
        this._hudMult();
      }
    }

    // ---- invasion line ---------------------------------------------------------------
    if (this.formation.findLineCrosser()) { this._gameOver('invasion'); return; }

    // ---- wave clear ------------------------------------------------------------------
    if (this.formation.allDead) this._waveClear();
  }

  _alienFireTick(dt) {
    const ratio = this.formation.aliveRatio;
    const panic = Math.pow(1 - ratio, WAVES.FIRE_CURVE_POW); // 0 full grid → 1 last alien
    const rate = WAVES.FIRE_RATE_BASE * (1 + panic * (WAVES.FIRE_RATE_PANIC - 1)) * waveFireMult(this.wave);
    this._fireAcc += dt * rate;
    while (this._fireAcc >= 1) {
      this._fireAcc -= 1;
      this._alienShoot();
    }
  }

  _alienShoot() {
    // Rejection-sample a live slot, then fire from the lowest alien in that column.
    let src = null;
    for (let tries = 0; tries < 8 && !src; tries++) {
      const idx = (Math.random() * this.formation.total) | 0;
      const s = this.formation.slots[idx];
      if (!s.alive) continue;
      src = this.formation.lowestInColumn(idx % GRID.COLS);
    }
    if (!src) return;

    const b = this.bullets.fireAlien(src.x, src.z, waveAlienBulletSpeed(this.wave));
    if (b && b.trail === undefined) {
      b.trail = this.trails.acquire(0xff8a5d, 0.12); // late-wave tracer read
    }
  }

  _ufoTick(dt) {
    const u = this.ufo;
    if (!u.active) {
      this._ufoTimer -= dt;
      if (this._ufoTimer <= 0 && !u.active) {
        if (u.spawn()) {
          this.audio.ufoStart();
          u.trailId = this.trails.acquire(0xff4d6d, 0.2);
        }
      }
    } else {
      const ev = u.update(dt);
      if (u.trailId !== undefined && u.trailId !== null) this.trails.push(u.trailId, u.x, u.y + 0.4, u.z);
      if (ev === 'exit') this._releaseUfoTrail();
    }
  }

  _releaseUfoTrail() {
    const u = this.ufo;
    if (u.trailId !== undefined && u.trailId !== null) {
      this.trails.release(u.trailId);
      u.trailId = null;
    }
  }

  // ============================================================== collision core

  _collisions(bres) {
    const p = bres.player;

    // 1 · player bullet vs aliens — swept test per live slot (tunneling-proof:
    // the full step segment is tested, so no alien can be skipped at any speed).
    if (p) {
      for (const s of this.formation.slots) {
        if (!s.alive) continue;
        if (this._segHitsCircle(p.px, p.pz, p.x, p.z, s.x, s.z, ALIEN_RADIUS + 0.25)) {
          this._killAlien(s);
          this.bullets.killPlayerBullet();
          break; // first alien along the path wins — classic behavior
        }
      }
    }

    // 2 · player bullet vs UFO (behind the formation line).
    if (p && p.active && this.ufo.active) {
      const u = this.ufo;
      if (this._segHitsCircle(p.px, p.pz, p.x, p.z, u.x, u.z, UFO.HIT_RADIUS)) {
        this._killUfo();
        this.bullets.killPlayerBullet();
      }
    }

    // 3 · player bullet vs bunkers (erodes, then the shot is spent).
    if (p && p.active) {
      const seg = this.bullets.playerSegment();
      if (seg) {
        const n = this.bunkers.erodeSegment(seg.ax, seg.az, seg.bx, seg.bz);
        if (n > 0) {
          this._bunkerEroded(n, p.x, BUNKERS.Z);
          this.bullets.killPlayerBullet();
        }
      }
    }

    // 4 · alien bullets vs player.
    const pl = this.player;
    if (pl.alive && !pl.isInvulnerable()) {
      for (const b of bres.aliens) {
        if (!b.active) continue;
        if (this._segHitsCircle(b.px, b.pz, b.x, b.z, pl.x, WORLD.PLAYER_Z, PLAYER.HIT_RADIUS + 0.3)) {
          this.bullets.alienPool.release(b);
          this._releaseBulletTrail(b);
          this._playerHit();
          break; // one hit per step — the rest keep flying (classic)
        }
      }
    }

    // 5 · alien bullets vs bunkers.
    for (const b of bres.aliens) {
      if (!b.active) continue;
      const seg = this.bullets.alienSegment(b);
      if (!seg) continue;
      const n = this.bunkers.erodeSegment(seg.ax, seg.az, seg.bx, seg.bz);
      if (n > 0) {
        this._bunkerEroded(n, b.x, BUNKERS.Z);
        this.bullets.alienPool.release(b);
        this._releaseBulletTrail(b);
      }
    }

    // Reap trails of bullets that were culled this step.
    if (this._trailPlayerId !== null && !this.bullets.playerLiveCount) {
      this.trails.release(this._trailPlayerId);
      this._trailPlayerId = null;
    }
  }

  _segHitsCircle(ax, az, bx, bz, tx, tz, radius) {
    const abx = bx - ax, abz = bz - az;
    const len2 = abx * abx + abz * abz;
    let t = len2 > 0 ? ((tx - ax) * abx + (tz - az) * abz) / len2 : 0;
    if (t < 0) t = 0; else if (t > 1) t = 1;
    const cx = ax + abx * t - tx, cz = az + abz * t - tz;
    return cx * cx + cz * cz <= radius * radius;
  }

  _releaseBulletTrail(b) {
    if (b.trail !== undefined && b.trail !== null) {
      this.trails.release(b.trail);
      b.trail = null;
    }
  }

  // ============================================================== event handlers

  _killAlien(slot) {
    const type = slot.type;
    const colorHex = TYPE_COLORS[type];
    const base = TYPE_SCORES[type];

    // Combo: first kill of a chain scores ×1, each chained kill raises toward the cap.
    if (this.comboTimer > 0) this.combo = Math.min(SCORING.COMBO_MAX, this.combo + 1);
    else this.combo = 1;
    this.comboTimer = SCORING.COMBO_WINDOW;

    const pts = base * this.combo;
    this._addScore(pts);

    // VFX — plan §4 tables.
    const cx = slot.x, cy = GRID.Y_BASE + 0.3, cz = slot.z;
    const count = Math.max(VFX.COUNT_ALIEN_KILL_MIN, base * (1 + this.combo * 0.25) | 0);
    this.particles.burst(cx, cy, cz, count, { color: colorHex, speed: 7 + this.combo, priority: VFX.PR_ALIEN_KILL, upBias: 0.4 });
    this.rings.spawn(cx, cy, cz, { color: colorHex, maxScale: 2.6, life: 0.45, orient: 'billboard' });
    this.shake.add(VFX.SHAKE_ALIEN_KILL_BASE + VFX.SHAKE_ALIEN_KILL_COMBO * (this.combo - 1));
    this.scoreText.spawn(cx, cy + 1.2, cz, `+${pts}${this.combo > 1 ? ` ×${this.combo}` : ''}`, this._hexCss(colorHex));

    this.audio.alienKill(0.8 + base / 60);
    this.formation.kill(slot);
    this.audio.setAliveRatio(this.formation.aliveRatio);
    this._hudMult();
  }

  _killUfo() {
    const u = this.ufo;
    // Weighted classic score table: 50/100/150/300 @ 40/30/20/10.
    let r = Math.random() * 100, pts = 50;
    if (r < 40) pts = 50; else if (r < 70) pts = 100; else if (r < 90) pts = 150; else pts = 300;

    this._addScore(pts);
    this.audio.ufoKill();
    this.hitstop.trigger(VFX.HITSTOP_UFO_KILL_MS, VFX.HITSTOP_UFO_KILL_SCALE);
    this.shake.add(VFX.SHAKE_UFO_KILL);
    this.particles.burst(u.x, u.y, u.z, VFX.COUNT_UFO_KILL, { color: 0xff4d6d, speed: 12, priority: VFX.PR_UFO_KILL, upBias: 0.5 });
    for (let i = 0; i < 3; i++) {
      this.rings.spawn(u.x, u.y, u.z, { color: 0xff4d6d, maxScale: 2 + i * 2.4, life: 0.5 + i * 0.18, orient: 'billboard' });
    }
    this.scoreText.spawn(u.x, u.y + 1.6, u.z, `+${pts}`, '#ff9db4');
    this.audio.rumble(0.7, 120);

    u.deactivate();
    this._releaseUfoTrail();
  }

  _playerHit() {
    const p = this.player;
    p.die();
    this.combo = 1;
    this.comboTimer = 0;
    this.lives--;

    // Full VFX weight — the moment that costs a life (plan §4.3).
    this.audio.playerHit();
    this.hitstop.trigger(VFX.HITSTOP_PLAYER_HIT_MS, VFX.HITSTOP_PLAYER_HIT_SCALE);
    this.shake.add(VFX.SHAKE_PLAYER_HIT);
    this.flashAlpha = 1;
    this.particles.burst(p.x, p.y + 0.4, WORLD.PLAYER_Z, VFX.COUNT_PLAYER_DEATH, { color: 0x66ffff, speed: 13, priority: VFX.PR_PLAYER_DEATH, upBias: 0.55 });
    this.particles.burst(p.x, p.y + 0.4, WORLD.PLAYER_Z, 24, { color: 0xffb347, speed: 9, priority: VFX.PR_PLAYER_DEATH, upBias: 0.6 });
    this.rings.spawn(p.x, 0.35, WORLD.PLAYER_Z, { color: 0x66ffff, maxScale: 7, life: 0.7, orient: 'floor' });
    this.scoreText.spawn(p.x, p.y + 2.4, WORLD.PLAYER_Z, this.lives > 0 ? 'SHIP LOST' : 'FINAL SHIP', '#ff5d8f');
    this.audio.rumble(1.0, 160);

    if (this._trailPlayerId !== null) { this.trails.release(this._trailPlayerId); this._trailPlayerId = null; }

    if (this.lives <= 0) {
      // Let the explosion breathe before the game-over screen (real-time clock).
      this._pendingGameOver = true;
      this._overDelay = 2.4;
    } else {
      this.deathTimer = 1.5; // respawn countdown — sim clock, decremented in _updatePlaying
    }
    this._hudSync(true);
  }

  _bunkerEroded(n, x, z) {
    const chips = Math.min(VFX.BUNKER_CHIPS_PER_CLUSTER * n, 24);
    this.particles.burst(x, BUNKERS.BASE_Y + 0.6, z, chips, { color: 0x37e6ff, speed: 5, priority: VFX.PR_BUNKER_CHIPS, upBias: 0.8 });
    this.rings.spawn(x, 0.4, z, { color: 0x37e6ff, maxScale: 1.4 + n * 0.25, life: 0.35, orient: 'floor' });
    this.shake.add(Math.min(0.6, VFX.SHAKE_BUNKER_EROSION * Math.min(n, 4)));
  }

  // ====================================================================== scoring

  _addScore(pts) {
    this.score += pts;
    while (this.score >= this.nextLifeAt) {
      this.lives++;
      this.nextLifeAt += SCORING.EXTRA_LIFE_EVERY;
      this.scoreText.spawn(this.player.x, this.player.y + 3.2, WORLD.PLAYER_Z - 1, 'EXTRA SHIP', '#ffb347');
      this.audio.uiBlip(990);
    }
    if (this.score > this.hiScore) {
      this.hiScore = this.score;
      try { localStorage.setItem(HI_SCORE_KEY, String(this.hiScore)); } catch { /* storage blocked */ }
    }
    this._hudSync(false);
  }

  // ======================================================================= hud

  _hexCss(hex) { return `#${hex.toString(16).padStart(6, '0')}`; }

  _hudMult() {
    const v = this.combo;
    this._multValEl.textContent = `×${v}`;
    this._multValEl.classList.toggle('hot', v >= 4);
    const t = (v - 1) / (SCORING.COMBO_MAX - 1);
    this._multFillEl.style.width = `${(t * 100).toFixed(1)}%`;
  }

  _hudSync(force) {
    if (force || this._lastScore !== this.score) {
      this._scoreEl.textContent = String(this.score);
      this._hiEl.textContent = `HI ${this.hiScore}`;
      this._lastScore = this.score;
    }
    if (force || this._lastWave !== this.wave) {
      this._waveEl.textContent = String(this.wave);
      this._lastWave = this.wave;
    }
    if (force || this._lastLives !== this.lives) {
      let html = '';
      for (let i = 0; i < Math.min(this.lives, 6); i++) html += '<span class="life-glyph"></span>';
      if (this.lives > 6) html += `<span style="color:var(--neon-cyan);font-size:12px">+${this.lives - 6}</span>`;
      this._livesEl.innerHTML = html || '<span style="opacity:.4;font-size:11px">—</span>';
      this._lastLives = this.lives;
    }
    if (force) this._hudMult();
  }

  // ==================================================================== realtime

  _realtimeUpdate(dt) {
    // Feedback systems run at full rate even during hit-stop (plan §4.4).
    this.particles.update(dt);
    this.trails.update(dt);
    this.rings.update(dt);
    this.scoreText.update(dt);
    this.shake.update(dt);

    // Apply shake offset to the camera (base position + trauma offset).
    const off = this.shake.getOffset(this._off);
    this.camera.position.set(CAMERA.POS[0] + off.x, CAMERA.POS[1] + off.y, CAMERA.POS[2] + off.z);

    // Impact flash decay.
    if (this.flashAlpha > 0) {
      this.flashAlpha = Math.max(0, this.flashAlpha - dt * 3.2);
      this._flashEl.style.opacity = this.flashAlpha.toFixed(3);
    }

    // March sequencer — the accelerating invader heartbeat (real-time driven).
    if (this.state === STATE.PLAYING) {
      this.audio.setAliveRatio(this.formation.aliveRatio);
      this.audio.updateMarch(dt);
    }

    // Deferred game-over after the death explosion has played out.
    if (this._pendingGameOver && this.deathTimer > 0) {
      this.deathTimer -= dt;
      if (this.deathTimer <= 0) {
        this._pendingGameOver = false;
        this._gameOver('lives');
      }
    }
  }

  // ======================================================================= misc

  /** Exposed for BulletSystem-style external kill of the single player bullet. */
  _killPlayerBullet() { this.bullets.killPlayerBullet(); }
}

// Space_Invaders/entities/BulletSystem.js
// Pooled player + alien bullets. Classic caps: 1 live player bullet, 3 live alien
// bullets. All collision tests are swept segment–circle in XZ (tunneling-proof at
// any frame rate). Zero allocation in the hot path — fixed pools, scratch vectors.

import * as THREE from 'three';
import ObjectPool from '../../shared/core/ObjectPool.js';
import { clamp } from '../../shared/utils/math.js';
import { BULLET, PLAYER, WORLD } from '../config.js';

const _v = new THREE.Vector3();

function makeBulletMesh(geo, mat) {
  const m = new THREE.Mesh(geo, mat);
  m.visible = false;
  return m;
}

export class BulletSystem {
  /**
   * @param scene THREE.Scene
   * @param mats { playerGeo, playerMat, alienGeo, alienMat } — shared geometry/materials
   */
  constructor(scene, mats) {
    this.scene = scene;

    // Player bullets: single live instance (classic rule). `seg` is a persistent
    // struct so erosion queries never allocate.
    this.playerBullet = {
      mesh: makeBulletMesh(mats.playerGeo, mats.playerMat),
      active: false, x: 0, z: 0, px: 0, pz: 0, seg: { ax: 0, az: 0, bx: 0, bz: 0 },
    };
    scene.add(this.playerBullet.mesh);

    // Alien bullets: pool of 3 (classic cap).
    this.alienPool = new ObjectPool(() => ({
      mesh: makeBulletMesh(mats.alienGeo, mats.alienMat),
      active: false, x: 0, z: 0, px: 0, pz: 0, speed: BULLET.ALIEN_BASE_SPEED,
      trail: null, // motion-trail slot id — released via onBulletReleased when the bullet dies
    }), BULLET.ALIEN_MAX_LIVE);
    for (const b of this.alienPool.items) scene.add(b.mesh);

    // Scratch for swept tests.
    this._seg = { x: 0, z: 0 };
  }

  get playerLiveCount() { return this.playerBullet.active ? 1 : 0; }
  get alienLiveCount() { let n = 0; for (const b of this.alienPool.items) if (b.active) n++; return n; }

  /** Fire the single player bullet from the ship. Returns true when fired. */
  firePlayer(x, z) {
    const p = this.playerBullet;
    if (p.active) return false; // classic: max one live
    p.active = true;
    p.x = x; p.z = z; p.px = x; p.pz = z;
    p.mesh.visible = true;
    p.mesh.position.set(x, PLAYER.Y, z);
    return true;
  }

  /** Fire one alien bullet from (x,z) toward the player line. Returns the bullet or null when capped. */
  fireAlien(x, z, speed) {
    const b = this.alienPool.acquire();
    if (!b) return null; // cap reached — classic behavior: shot is lost
    b.x = x; b.z = z; b.px = x; b.pz = z; b.speed = speed;
    b.mesh.visible = true;
    b.mesh.position.set(x, 1.0, z);
    return b;
  }

  /** Advance all bullets one sim step. Returns { player: bullet|null, aliens: [bullet] }. */
  update(dt) {
    const p = this.playerBullet;
    if (p.active) {
      p.px = p.x; p.pz = p.z;
      p.z -= BULLET.PLAYER_SPEED * dt;
      p.mesh.position.set(p.x, PLAYER.Y, p.z);
      // Persistent segment for erosion queries — no allocation per call.
      p.seg.ax = p.px; p.seg.az = p.pz; p.seg.bx = p.x; p.seg.bz = p.z;
      if (p.z < WORLD.Z_FAR_LIMIT) this._killPlayerBullet();
    }

    const live = [];
    for (const b of this.alienPool.items) {
      if (!b.active) continue;
      b.px = b.x; b.pz = b.z;
      b.z += b.speed * dt;
      b.mesh.position.set(b.x, 1.0, b.z);
      if (b.z > WORLD.Z_NEAR_LIMIT) { this._releaseAlien(b); continue; }
      live.push(b);
    }
    return { player: p.active ? p : null, aliens: live };
  }

  _killPlayerBullet() {
    const p = this.playerBullet;
    p.active = false;
    p.mesh.visible = false;
  }

  /** Public kill — the orchestrator calls this when a hit is resolved. */
  killPlayerBullet() { this._killPlayerBullet(); }

  /** Swept test: did the player bullet's segment pass within radius of (tx,tz)? */
  playerHitTest(tx, tz, radius) {
    const p = this.playerBullet;
    if (!p.active) return false;
    return segmentCircleXZ(p.px, p.pz, p.x, p.z, tx, tz, radius);
  }

  /** Swept test against one alien bullet. */
  alienHitTest(b, tx, tz, radius) {
    if (!b.active) return false;
    return segmentCircleXZ(b.px, b.pz, b.x, b.z, tx, tz, radius);
  }

  /** Persistent player-bullet segment (updated each step in update()). Null when inactive. */
  playerSegment() {
    const p = this.playerBullet;
    return p.active ? p.seg : null;
  }

  /** Persistent alien-bullet segment for bunker erosion — no allocation per call. */
  alienSegment(b) {
    if (!b.active || !b.seg) return null;
    b.seg.ax = b.px; b.seg.az = b.pz; b.seg.bx = b.x; b.seg.bz = b.z;
    return b.seg;
  }

  /** Internal release: notify the trail owner (if wired), then pool the bullet. */
  _releaseAlien(b) {
    if (this.onBulletReleased) this.onBulletReleased(b);
    this.alienPool.release(b);
  }

  clearAll() {
    if (this.playerBullet.active) this._killPlayerBullet();
    this.alienPool.releaseAll();
  }

  dispose() {
    this.scene.remove(this.playerBullet.mesh);
    for (const b of this.alienPool.items) this.scene.remove(b.mesh);
  }
}

// Local swept test (XZ only — bullets travel along Z, targets are point-circles).
function segmentCircleXZ(ax, az, bx, bz, px, pz, radius) {
  const abx = bx - ax;
  const abz = bz - az;
  const apx = px - ax;
  const apz = pz - az;
  const len2 = abx * abx + abz * abz;
  let t = len2 > 0 ? (apx * abx + apz * abz) / len2 : 0;
  t = clamp(t, 0, 1);
  const cx = ax + abx * t - px;
  const cz = az + abz * t - pz;
  return cx * cx + cz * cz <= radius * radius;
}

/**
 * InputController — unified dual-input (Keyboard + Gamepad API) into one polled state.
 *
 * Game code NEVER touches raw keydown / navigator.getGamepads(). It polls:
 *   input.update()          // call once per frame, before sim steps
 *   input.axes.x            // -1..+1 merged keyboard+gamepad (deadzone + smoothstep shaped)
 *   input.fire              // held fire (keyboard Space/Enter OR gamepad A / RT)
 *   input.consumeEdge(name) // edge-triggered events: 'fire', 'pause', 'start'
 *
 * Keyboard and gamepad are merged, not sourced — a disconnected pad degrades to
 * keyboard seamlessly. Edge events are queued with a 1-frame grace so they survive
 * being polled after update().
 */

const KEY_LEFT = new Set(['KeyA', 'ArrowLeft']);
const KEY_RIGHT = new Set(['KeyD', 'ArrowRight']);
const KEY_FIRE = new Set(['Space', 'Enter', 'KeyJ']);
const KEY_PAUSE = new Set(['Escape', 'KeyP']);
const KEY_START = new Set(['Enter', 'KeyR']);

function shapeAxis(v) {
  const s = Math.sign(v);
  const a = Math.min(1, Math.abs(v));
  return s * (a * a * (3 - 2 * a)); // smoothstep — fine control near center
}

export class InputController {
  constructor() {
    this.axes = { x: 0, y: 0 };
    this.fire = false;
    this.pauseHeld = false;
    this.startHeld = false;

    this._keysDown = new Set();
    this._padIndex = null;
    this._edges = [];          // { name } — queued edge events
    this._prevFire = false;
    this._prevPause = false;
    this._prevStart = false;
    this._graceFrames = 0;     // frames an edge stays consumable after being raised

    this._onKeyDown = (e) => {
      if (KEY_FIRE.has(e.code)) e.preventDefault();
      this._keysDown.add(e.code);
    };
    this._onKeyUp = (e) => { this._keysDown.delete(e.code); };
    this._onBlur = () => { this._keysDown.clear(); };
    this._onGamepad = () => { this._detectPad(); };

    window.addEventListener('keydown', this._onKeyDown, { passive: false });
    window.addEventListener('keyup', this._onKeyUp);
    window.addEventListener('blur', this._onBlur);
    if (typeof navigator !== 'undefined' && typeof navigator.getGamepads === 'function') {
      window.addEventListener('gamepadconnected', this._onGamepad);
      window.addEventListener('gamepaddisconnected', this._onPadDisconnect);
    }
  }

  _detectPad() {
    const pads = navigator.getGamepads();
    for (const p of pads) if (p && p.connected) { this._padIndex = p.index; return; }
  }

  _onPadDisconnect = (e) => {
    if (this._padIndex === e.gamepad?.index) this._padIndex = null;
  };

  /** Poll all sources, merge into axes/fire, raise edge events. Call once per frame. */
  update() {
    // ---- keyboard axis ----
    let kx = 0;
    for (const code of this._keysDown) {
      if (KEY_LEFT.has(code)) kx -= 1;
      else if (KEY_RIGHT.has(code)) kx += 1;
    }

    // ---- gamepad axis + buttons ----
    let gx = 0, gFire = false, gPause = false, gStart = false;
    const pad = this._readPad();
    if (pad) {
      const ax = pad.axes[0] ?? 0;
      if (Math.abs(ax) > 0.18) gx = shapeAxis(ax); // deadzone then smoothstep
      gFire = !!(pad.buttons[0]?.pressed || pad.buttons[5]?.pressed || pad.buttons[7]?.pressed);
      gPause = !!pad.buttons[9]?.pressed;
      gStart = !!pad.buttons[3]?.pressed;
    }

    // ---- merge (gamepad wins on axis when both active) ----
    this.axes.x = Math.abs(gx) > 0.01 ? gx : kx;
    const kbFire = [...this._keysDown].some((c) => KEY_FIRE.has(c));
    this.fire = gFire || kbFire;
    this.pauseHeld = gPause || [...this._keysDown].some((c) => KEY_PAUSE.has(c));
    this.startHeld = gStart || [...this._keysDown].some((c) => KEY_START.has(c));

    // ---- edge detection (rising edges only) ----
    if (this.fire && !this._prevFire) this._raise('fire');
    if (this.pauseHeld && !this._prevPause) this._raise('pause');
    if (this.startHeld && !this._prevStart) this._raise('start');

    this._prevFire = this.fire;
    this._prevPause = this.pauseHeld;
    this._prevStart = this.startHeld;

    // edges survive 2 frames after being raised so consumers polled later in the frame still see them
    if (this._graceFrames > 0) this._graceFrames--;
    else if (this._edges.length) this._edges.length = 0;
  }

  _readPad() {
    try {
      const pads = navigator.getGamepads();
      return pads?.[this._padIndex ?? 0] || null;
    } catch { return null; }
  }

  _raise(name) { this._edges.push({ name }); this._graceFrames = 2; }

  /** Consume a queued edge event if present (returns true once). */
  consumeEdge(name) {
    const i = this._edges.findIndex((e) => e.name === name);
    if (i >= 0) { this._edges.splice(i, 1); return true; }
    return false;
  }

  /** Remove listeners. Idempotent. */
  dispose() {
    window.removeEventListener('keydown', this._onKeyDown);
    window.removeEventListener('keyup', this._onKeyUp);
    window.removeEventListener('blur', this._onBlur);
    if (typeof navigator !== 'undefined' && typeof navigator.getGamepads === 'function') {
      window.removeEventListener('gamepadconnected', this._onGamepad);
      window.removeEventListener('gamepaddisconnected', this._onPadDisconnect);
    }
  }
}

// AlienFormation — the 11×5 drone grid and its signature motion model.
//
// Classic behavior (plan §1.2): continuous X-march, discrete Z step-down on each
// wall bounce. Speed is a monotonic function of kills:
//   v = lerp(9, 84, pow(1 - aliveRatio, 1.6)) * waveMult(wave)
// so the swarm can never slow down mid-wave and the last alien is frantic.

import * as THREE from 'three';
import { clamp, lerp } from '../../shared/utils/math.js';
import { WORLD, GRID, ALIEN_RADIUS, FORMATION, waveVXMult } from '../config.js';
import { buildAlienFrames } from './AlienTypes.js';

// Destructured once at module scope — the rest of this file uses the short names.
const COLS = GRID.COLS;
const ROWS = GRID.ROWS;
const X_BOUND = WORLD.X_BOUND;
const PLAYER_Z = WORLD.PLAYER_Z;
const DEFENSE_MARGIN = WORLD.DEFENSE_MARGIN;

const FRAME_PERIOD_BASE = 0.72; // s between march-frame swaps at full grid
const FRAME_PERIOD_MIN = 0.34;  // …and when the swarm is frantic

export class AlienFormation {
  /**
   * @param {THREE.Scene} scene
   * @param {import('../../shared/materials/NeonMaterials.js').NeonMaterials} mats
   */
  constructor(scene, mats) {
    this.scene = scene;
    this.mats = mats;

    // Shared geometries: 3 types × 2 frames. Owned (and disposed) by this class.
    // Type indices: 0 = squid (30 pts), 1 = octopus (20), 2 = crab (10) — see AlienTypes.
    const squidA = buildAlienFrames(0, mats);
    const octoA = buildAlienFrames(1, mats);
    const crabA = buildAlienFrames(2, mats);
    this._geos = [squidA, octoA, crabA]; // each: { a, b }

    // Row → type mapping (plan §1.1): farthest rows are the 30-pt squids.
    const rowType = [2, 1, 1, 0, 0]; // z=-8→crab(2), -10/-12→octo(1), -14/-16→squid(0)

    this.slots = [];
    for (let r = 0; r < ROWS; r++) {
      const z = GRID.Z_START + r * GRID.ROW_SPACING; // -8 … -16
      const typeIdx = rowType[r];
      for (let c = 0; c < COLS; c++) {
        const x = -(COLS - 1) / 2 * GRID.COL_SPACING + c * GRID.COL_SPACING;
        const geoPair = this._geos[typeIdx];
        const mesh = new THREE.Mesh(geoPair.a, [mats.hull(), mats.neon()]);
        mesh.position.set(x, GRID.Y_BASE, z);
        scene.add(mesh);
        this.slots.push({ x, z, type: typeIdx, alive: true, mesh, phase: Math.random() * 6.28 });
      }
    }

    this.direction = 1;
    this._frameA = true;
    this._frameTimer = 0;
    this._t = 0; // hover-bob clock
    this.total = COLS * ROWS;
    this.aliveCount = this.total;
  }

  get aliveRatio() { return this.aliveCount / this.total; }
  get allDead() { return this.aliveCount === 0; }

  /** Current march speed (u/s) including wave scaling. */
  currentSpeed(wave) {
    const base = lerp(9, 84, Math.pow(1 - this.aliveRatio, 1.6));
    return base * waveVXMult(wave);
  }

  /**
   * Advance the formation one fixed step.
   * @returns {{steppedDown:boolean}} whether a wall bounce occurred this step
   */
  update(dt, wave) {
    const v = this.currentSpeed(wave);
    let steppedDown = false;

    // March X.
    for (const s of this.slots) {
      if (!s.alive) continue;
      s.x += this.direction * v * dt;
    }

    // Wall check on the live extremes only (dead slots never trigger bounces).
    let minX = Infinity, maxX = -Infinity;
    for (const s of this.slots) {
      if (!s.alive) continue;
      if (s.x < minX) minX = s.x;
      if (s.x > maxX) maxX = s.x;
    }

    if (this.direction > 0 && maxX + ALIEN_RADIUS >= X_BOUND) {
      this.direction = -1;
      steppedDown = true;
    } else if (this.direction < 0 && minX - ALIEN_RADIUS <= -X_BOUND) {
      this.direction = 1;
      steppedDown = true;
    }

    if (steppedDown) {
      // One discrete row-step toward the player line — the classic step-down.
      for (const s of this.slots) if (s.alive) s.z += GRID.STEP_DOWN;
    }

    // March-frame swap: period shrinks as the swarm accelerates (visual sync with audio tempo).
    const period = lerp(FRAME_PERIOD_BASE, FRAME_PERIOD_MIN, Math.pow(1 - this.aliveRatio, 1.5));
    this._frameTimer += dt;
    if (this._frameTimer >= period) {
      this._frameTimer = 0;
      this._toggleFrame();
    }

    // Hover bob — subtle life under the PBR rim lights.
    this._t += dt;
    for (const s of this.slots) {
      if (!s.alive) continue;
      const m = s.mesh;
      m.position.x = s.x;
      m.position.z = s.z;
      m.position.y = GRID.Y_BASE + Math.sin(this._t * 2.1 + s.phase) * 0.14;
    }

    return { steppedDown };
  }

  _toggleFrame() {
    this._frameA = !this._frameA;
    for (const s of this.slots) {
      if (!s.alive) continue;
      const pair = this._geos[s.type];
      s.mesh.geometry = this._frameA ? pair.a : pair.b;
    }
  }

  /** Kill one alien. Returns its slot (with type + position) for scoring/VFX. */
  kill(slot) {
    if (!slot.alive) return null;
    slot.alive = false;
    slot.mesh.visible = false;
    this.aliveCount--;
    return slot;
  }

  /** Lowest live alien (max z, i.e. closest to player) in a column — the fire source. */
  lowestInColumn(col) {
    let best = null;
    // Columns are implicit in slot order: index = row*COLS + col.
    for (let r = 0; r < ROWS; r++) {
      const idx = r * COLS + col;
      const s = this.slots[idx];
      if (s.alive && (!best || s.z > best.z)) best = s;
    }
    return best;
  }

  /** First live alien that has crossed the defense line, or null. */
  findLineCrosser() {
    const limit = PLAYER_Z - DEFENSE_MARGIN;
    for (const s of this.slots) if (s.alive && s.z >= limit) return s;
    return null;
  }

  /** Rebuild the full grid at wave start. */
  reset(wave) {
    void wave; // future: per-wave formation variants
    let i = 0;
    for (let r = 0; r < ROWS; r++) {
      const z = GRID.Z_START + r * GRID.ROW_SPACING;
      for (let c = 0; c < COLS; c++, i++) {
        const s = this.slots[i];
        s.x = -(COLS - 1) / 2 * GRID.COL_SPACING + c * GRID.COL_SPACING;
        s.z = z;
        s.alive = true;
        s.mesh.visible = true;
      }
    }
    this.direction = 1;
    this._frameA = true;
    this._frameTimer = 0;
    this.aliveCount = this.total;
    for (const s of this.slots) {
      const pair = this._geos[s.type];
      s.mesh.geometry = pair.a;
      s.mesh.position.set(s.x, GRID.Y_BASE, s.z);
    }
  }

  dispose() {
    for (const s of this.slots) this.scene.remove(s.mesh);
    for (const pair of this._geos) {
      pair.a.dispose();
      pair.b.dispose();
    }
  }
}

// Space_Invaders/entities/PlayerShip.js
// The player's hover-ship: procedural low-poly hull (swept wings + canopy),
// single-axis movement along X, fire cooldown gate, and a fair circular hitbox.

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { clamp } from '../../shared/utils/math.js';
import { PLAYER, WORLD } from '../config.js';

export class PlayerShip {
  /**
   * @param {THREE.Scene} scene
   * @param {object} mats NeonMaterials instance (hull/neon/dark presets)
   */
  constructor(scene, mats) {
    this.scene = scene;
    this.x = 0;
    this.y = PLAYER.Y; // hover height above the floor plane
    this.z = WORLD.PLAYER_Z; // fixed depth line

    this.fireCooldown = 0;      // seconds remaining before next shot is allowed
    this.invulnTime = 0;        // post-hit grace window (classic: brief mercy after respawn)
    this.alive = true;
    this.thrustPhase = 0;       // thruster pulse animation clock

    this.group = new THREE.Group();
    this._buildHull(mats);
    scene.add(this.group);
  }

  _box(w, h, d, x, y, z, matIdx) {
    const g = new THREE.BoxGeometry(w, h, d);
    g.translate(x, y, z);
    if (matIdx !== undefined) g.clearGroups(); // single-material merge keeps groups simple
    return g;
  }

  _buildHull(mats) {
    // Hull pieces — all merged into one geometry with per-part material indices.
    const parts = [
      // Central fuselage: a tapered box (two stacked boxes for the taper).
      this._box(1.5, 0.42, 3.4, 0, 0.18, 0),
      this._box(0.9, 0.34, 2.6, 0, 0.52, -0.2),
      // Swept wings: thin boxes angled back.
      (() => { const g = new THREE.BoxGeometry(1.7, 0.1, 1.5); g.rotateY(-0.42); g.translate(-1.35, 0.16, 0.55); return g; })(),
      (() => { const g = new THREE.BoxGeometry(1.7, 0.1, 1.5); g.rotateY(0.42); g.translate(1.35, 0.16, 0.55); return g; })(),
      // Canopy: small emissive dome-ish box on top.
      this._box(0.7, 0.3, 1.1, 0, 0.82, -0.3),
      // Twin thruster nozzles at the rear.
      this._box(0.42, 0.3, 0.5, -0.55, 0.2, 1.75),
      this._box(0.42, 0.3, 0.5, 0.55, 0.2, 1.75),
    ];

    const merged = mergeGeometries(parts, false);
    parts.forEach((g) => g.dispose()); // source geometries are consumed by the merge

    this.hullMat = mats.hull(0x2a3854);
    this.canopyMat = mats.neon(0x66ffff, 2.6);
    this.thrusterMat = mats.neon(0xff9e3d, 3.2);

    // Assign material indices: canopy = part 4, thrusters = parts 5 & 6.
    const geo = merged;
    geo.clearGroups();
    const posCount = geo.attributes.position.count;
    // Each box is 24 verts (BoxGeometry). Parts are in order above.
    const per = 24;
    geo.addGroup(0, per * 4, 0);            // fuselage + wings → hull
    geo.addGroup(per * 4, per, 1);          // canopy → neon cyan
    geo.addGroup(per * 5, per * 2, 2);      // thrusters → neon amber

    this.mesh = new THREE.Mesh(geo, [this.hullMat, this.canopyMat, this.thrusterMat]);
    this.group.add(this.mesh);

    // Thruster glow cores (small emissive boxes just behind the nozzles) — pulse while moving.
    const coreGeo = new THREE.BoxGeometry(0.3, 0.2, 0.5);
    this.thrusterCoreL = new THREE.Mesh(coreGeo, mats.neon(0xffc46b, 4.0));
    this.thrusterCoreR = new THREE.Mesh(coreGeo.clone(), mats.neon(0xffc46b, 4.0));
    this.thrusterCoreL.position.set(-0.55, 0.2, 2.1);
    this.thrusterCoreR.position.set(0.55, 0.2, 2.1);
    this.group.add(this.thrusterCoreL, this.thrusterCoreR);
    this._coreGeo = coreGeo;
  }

  /** Integrate movement for one fixed sim step. `axisX` is the merged input axis (-1..+1). */
  update(dt, axisX, speed) {
    if (!this.alive) return;
    const prevX = this.x;
    this.x = clamp(this.x + axisX * speed * dt, -19, 19);

    // Fire cooldown always ticks (even when not firing).
    if (this.fireCooldown > 0) this.fireCooldown -= dt;
    if (this.invulnTime > 0) this.invulnTime -= dt;

    // Thruster pulse: faster while moving.
    const moving = Math.abs(axisX) > 0.05;
    this.thrustPhase += dt * (moving ? 26 : 8);
    const pulse = 0.7 + 0.3 * Math.sin(this.thrustPhase);
    const boost = moving ? 1.25 : 0.55;
    this.thrusterCoreL.scale.setScalar(pulse * boost);
    this.thrusterCoreR.scale.setScalar(pulse * boost);

    // Sync the group transform (render reads position directly — no interpolation needed,
    // movement is smooth at 120 Hz).
    this.group.position.set(this.x, this.y, this.z);
    void prevX;
  }

  /** Can the player fire right now? */
  canFire() { return this.alive && this.fireCooldown <= 0; }

  /** Consume a shot: sets cooldown and writes the muzzle world position into `out`. */
  consumeShot(cooldown, out) {
    this.fireCooldown = cooldown;
    out.x = this.x;
    out.y = this.y + 1.0;
    out.z = this.z - 1.6;
    return out;
  }

  /** Circular hitbox in XZ (generous vs the visual hull — fair arcade feel). */
  getHitRadius() { return 1.15; }

  /** Brief invulnerability window after a hit/respawn so the player isn't double-killed. */
  setInvuln(seconds) { this.invulnTime = seconds; }
  isInvulnerable() { return this.invulnTime > 0; }

  /** Death animation: sink + spin handled by Game via particles; here we just hide. */
  die() {
    this.alive = false;
    this.group.visible = false;
  }

  respawn() {
    this.alive = true;
    this.x = 0;
    this.fireCooldown = 0;
    this.invulnTime = 1.6; // mercy window — classic behavior after losing a life
    this.group.visible = true;
    this.group.position.set(this.x, this.y, this.z);
  }

  dispose() {
    this.scene.remove(this.group);
    if (this.mesh) this.mesh.geometry.dispose();
    [this.hullMat, this.canopyMat, this.thrusterMat].forEach((m) => m && m.dispose());
    if (this._coreGeo) this._coreGeo.dispose();
  }
}

