import * as THREE from 'three';

/**
 * NeonMaterials — MeshStandardMaterial factory with a shared cache.
 * PBR discipline: hulls stay dark (metalness .8 / roughness .3) so the two-tone
 * rim lights read on them; only designated emitters carry emissiveIntensity > 1,
 * which is what crosses the bloom threshold (0.82) in PostPipeline.
 */
export class NeonMaterials {
  constructor() {
    this._cache = new Map(); // signature -> material
  }

  /** Get-or-create a standard material from a spec object. */
  get(spec) {
    const key = JSON.stringify([spec.color, spec.metalness, spec.roughness, spec.emissive, spec.emissiveIntensity, spec.transparent, spec.opacity]);
    let mat = this._cache.get(key);
    if (mat) return mat;

    mat = new THREE.MeshStandardMaterial({
      color: spec.color ?? 0x1a2436,
      metalness: spec.metalness ?? 0.8,
      roughness: spec.roughness ?? 0.32,
      emissive: spec.emissive ?? 0x000000,
      emissiveIntensity: spec.emissiveIntensity ?? 1.0,
    });
    if (spec.transparent) { mat.transparent = true; mat.opacity = spec.opacity ?? 1; }
    this._cache.set(key, mat);
    return mat;
  }

  // Convenience presets used across the collection -------------------------

  hull(color = 0x232f47) {
    return this.get({ color, metalness: 0.85, roughness: 0.3 });
  }

  /** Glowing accent — crosses bloom threshold by design. */
  neon(color = 0x66ffff, intensity = 3.0) {
    return this.get({ color: 0x0a121c, metalness: 0.4, roughness: 0.5, emissive: color, emissiveIntensity: intensity });
  }

  /** Dark non-emissive accent (panel lines, joints). */
  dark(color = 0x131b2a) {
    return this.get({ color, metalness: 0.6, roughness: 0.55 });
  }

  disposeAll() {
    for (const mat of this._cache.values()) mat.dispose();
    this._cache.clear();
  }
}

// Space_Invaders/entities/Bunkers.js
// Destructible cover: 4 bunkers × ~80 live cells, ALL rendered by ONE InstancedMesh
// (single draw call). Erosion is symmetric — player and alien bullets carve identical
// craters. Dead cells are hidden with zero-scale matrices: no buffer rebuilds, no
// allocation in the hot path.

import * as THREE from 'three';
import { clamp } from '../../shared/utils/math.js';
import { BUNKERS } from '../config.js';

const COLS = 13;
const ROWS = 7;
const CELL = 0.42;
const CRATER_R = 1.15; // classic "bite" radius
const HALF_COLS = (COLS - 1) / 2;

// Arch cutout: cells inside this profile are never built (the entry notch).
function isArchCell(col, row) {
  if (row >= ROWS - 3 && col >= 4 && col <= 8) return true; // bottom-center opening
  if ((row === ROWS - 1 || row === ROWS - 2) && col >= 5 && col <= 7) return true;
  return false;
}

export class Bunkers {
  /**
   * @param scene THREE.Scene
   * @param mat THREE.Material — MeshStandardMaterial for the blocks (shared, owner disposes)
   */
  constructor(scene, mat) {
    this.scene = scene;

    // Cell grids: [bunker][row][col] → true when live.
    this.grids = [];
    const totalCells = BUNKERS.COUNT * COLS * ROWS;

    const geo = new THREE.BoxGeometry(CELL * 0.92, CELL * 0.8, CELL * 0.92);
    this._geo = geo;

    // One InstancedMesh for every block of every bunker (upper bound).
    const mesh = new THREE.InstancedMesh(geo, mat, totalCells);
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    mesh.frustumCulled = false;
    scene.add(mesh);
    this.mesh = mesh;

    // Flat cell index per instance slot (b*COLS*ROWS + r*COLS + c), -1 for unused tail.
    this._cellIndex = new Int32Array(totalCells).fill(-1);

    const m4 = new THREE.Matrix4();
    let idx = 0;
    for (let b = 0; b < BUNKERS.COUNT; b++) {
      const grid = [];
      const bx = BUNKERS.X_POSITIONS[b];
      for (let r = 0; r < ROWS; r++) {
        const rowArr = new Array(COLS).fill(false);
        for (let c = 0; c < COLS; c++) {
          if (isArchCell(c, r)) continue; // arch cutout — never built
          const x = bx + (c - HALF_COLS) * CELL;
          const y = BUNKERS.BASE_Y + r * CELL * 0.8;
          m4.makeTranslation(x, y, BUNKERS.Z);
          mesh.setMatrixAt(idx, m4);

          this._cellIndex[idx] = b * COLS * ROWS + r * COLS + c;
          rowArr[c] = true;
          idx++;
        }
        grid.push(rowArr);
      }
      this.grids.push(grid);
    }

    // Unused tail instances stay zero-scaled (hidden).
    const zero = new THREE.Matrix4().makeScale(0, 0, 0);
    for (let i = idx; i < totalCells; i++) mesh.setMatrixAt(i, zero);
    this._liveCount = idx; // instance slots that hold a real cell

    // Per-instance slight hue jitter: cyan → teal band.
    const col = new THREE.Color();
    for (let i = 0; i < this._liveCount; i++) {
      const t = Math.random() * 0.35;
      col.setRGB(0.1 + t * 0.2, 0.75 - t * 0.15, 0.9 - t * 0.2);
      mesh.setColorAt(i, col);
    }
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;

    this._m4 = m4;
    this.liveCells = idx; // live cell count for O(1) queries
  }

  /**
   * Erode all live cells whose centers fall within `radius` of the segment
   * [ax,az]→[bx,bz]. Returns the number of cells destroyed (0 when no hit).
   */
  erodeSegment(ax, az, bx, bz, radius = CRATER_R) {
    let destroyed = 0;
    const abx = bx - ax;
    const abz = bz - az;
    const len2 = abx * abx + abz * abz;

    for (let i = 0; i < this._liveCount; i++) {
      const flat = this._cellIndex[i];
      if (flat < 0) continue;
      const b = Math.floor(flat / (COLS * ROWS));
      const r = Math.floor((flat % (COLS * ROWS)) / COLS);
      const c = flat % COLS;
      if (!this.grids[b][r][c]) continue;

      const x = BUNKERS.X_POSITIONS[b] + (c - HALF_COLS) * CELL;
      // Swept segment–circle test in XZ.
      let t = len2 > 0 ? ((x - ax) * abx + (BUNKERS.Z - az) * abz) / len2 : 0;
      t = clamp(t, 0, 1);
      const cx = ax + abx * t - x;
      const cz = BUNKERS.Z - (az + abz * t);
      if (cx * cx + cz * cz <= radius * radius) {
        this.grids[b][r][c] = false;
        this._m4.makeScale(0, 0, 0);
        this.mesh.setMatrixAt(i, this._m4);
        destroyed++;
      }
    }

    if (destroyed > 0) {
      this.liveCells -= destroyed;
      this.mesh.instanceMatrix.needsUpdate = true;
    }
    return destroyed;
  }

  /** Rebuild all bunkers to full health (wave transition). */
  rebuild() {
    let i = 0; // instance cursor — mirrors construction order exactly
    for (let b = 0; b < BUNKERS.COUNT; b++) {
      const bx = BUNKERS.X_POSITIONS[b];
      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          if (isArchCell(c, r)) continue;
          const x = bx + (c - HALF_COLS) * CELL;
          const y = BUNKERS.BASE_Y + r * CELL * 0.8;
          this._m4.makeTranslation(x, y, BUNKERS.Z);
          this.mesh.setMatrixAt(i, this._m4);
          this.grids[b][r][c] = true; // restore live state — critical for next wave's erosion
          i++;
        }
      }
    }
    this.liveCells = i;
    this.mesh.instanceMatrix.needsUpdate = true;
  }

  /** True when any live cell exists (O(1)). */
  get hasLiveCells() { return this.liveCells > 0; }

  dispose() {
    this.scene.remove(this.mesh);
    this._geo.dispose(); // material is shared — owner disposes it
  }
}

// Space_Invaders/entities/UfoShip.js
// The mystery ship: one pooled UFO that crosses the far field on a warble.
// Spawn → fly X at fixed Z/Y → despawn off-screen, or die to a player bullet.

import * as THREE from 'three';
import { clamp } from '../../shared/utils/math.js';
import { UFO, WORLD } from '../config.js';

export class UfoShip {
  /**
   * @param scene THREE.Scene
   * @param mats { hull: Material, dome: Material, lights: Material } — all MeshStandardMaterial
   */
  constructor(scene, mats) {
    this.scene = scene;
    this.active = false;
    this.x = 0;
    this.px = 0; // previous x (for trail sampling + swept test)
    this.z = UFO.Z;
    this.y = UFO.Y;
    this.speed = UFO.SPEED;
    this.dir = 1;

    const group = new THREE.Group();

    // Saucer hull — flattened cylinder.
    const hullGeo = new THREE.CylinderGeometry(1.5, 1.9, 0.55, 24);
    const hull = new THREE.Mesh(hullGeo, mats.hull);
    group.add(hull);

    // Dome.
    const domeGeo = new THREE.SphereGeometry(0.75, 20, 12, 0, Math.PI * 2, 0, Math.PI / 2);
    const dome = new THREE.Mesh(domeGeo, mats.dome);
    dome.position.y = 0.3;
    group.add(dome);

    // Light ring — the emitter that blooms (emissiveIntensity > threshold).
    const lightGeo = new THREE.TorusGeometry(1.62, 0.09, 8, 40);
    const lights = new THREE.Mesh(lightGeo, mats.lights);
    lights.rotation.x = Math.PI / 2;
    lights.position.y = -0.1;
    group.add(lights);

    this.group = group;
    group.visible = false;
    scene.add(group);

    this._geos = [hullGeo, domeGeo, lightGeo];
  }

  /** Begin a crossing. Returns true when the UFO took off. */
  spawn() {
    if (this.active) return false;
    // Alternate direction each appearance for variety.
    this.dir *= -1;
    this.x = this.dir > 0 ? WORLD.UFO_ENTRY_X : -WORLD.UFO_ENTRY_X;
    this.px = this.x;
    this.speed = UFO.SPEED * (0.85 + Math.random() * 0.3);
    this.active = true;
    this.group.visible = true;
    return true;
  }

  /** Advance one sim step. Returns 'exit' when it left the arena, else null. */
  update(dt) {
    if (!this.active) return null;
    this.px = this.x;
    this.x += this.dir * this.speed * dt;
    const outX = WORLD.UFO_EXIT_X;
    if (Math.abs(this.x) > outX) {
      this.deactivate();
      return 'exit';
    }
    // Gentle bob for life.
    const t = performance.now() * 0.0021;
    this.group.position.set(this.x, this.y + Math.sin(t) * 0.18, this.z);
    this.group.rotation.z = -this.dir * 0.06;
    return null;
  }

  /**
   * Swept test against a bullet segment (ax,az)→(bx,bz): the UFO flies along X at
   * fixed Z. Find where the bullet crosses that Z plane; if it does within its own
   * step and near the UFO's swept X span, it's a hit.
   */
  hitTest(ax, az, bx, bz, radius) {
    if (!this.active) return false;
    const dz = bz - az;
    let crossT;
    if (Math.abs(dz) < 1e-9) {
      // Bullet parallel to the flight line — only hits if it's ON this Z plane.
      if (Math.abs(az - this.z) > radius) return false;
      crossT = 0.5;
    } else {
      crossT = (this.z - az) / dz;
      if (crossT < 0 || crossT > 1) return false; // didn't reach the UFO's depth this step
    }
    const cxAtCross = ax + (bx - ax) * crossT;
    // UFO swept span between px and x, inflated by radius.
    const lo = Math.min(this.px, this.x) - radius;
    const hi = Math.max(this.px, this.x) + radius;
    return cxAtCross >= lo && cxAtCross <= hi;
  }

  deactivate() {
    this.active = false;
    this.group.visible = false;
  }

  dispose() {
    this.scene.remove(this.group);
    for (const g of this._geos) g.dispose();
  }
}

import * as THREE from 'three';
import { clamp } from '../utils/math.js';

/**
 * ShockwaveRings — pooled expanding emissive rings for impacts and deaths.
 * Each ring is a thin torus; orientation context: "floor" (flat on XZ) or
 * "billboard" (faces camera). Scale grows, opacity fades over lifetime.
 */
export class ShockwaveRings {
  constructor(scene, { max = 12 } = {}) {
    this.scene = scene;
    this.max = max;

    const geo = new THREE.TorusGeometry(0.5, 0.035, 8, 48);
    const mat = new THREE.MeshStandardMaterial({
      color: 0x0a121c, metalness: 0.3, roughness: 0.5,
      emissive: 0xffffff, emissiveIntensity: 3.6,
      transparent: true, opacity: 1, depthWrite: false,
    });

    this.rings = [];
    for (let i = 0; i < max; i++) {
      const mesh = new THREE.Mesh(geo, mat.clone());
      mesh.visible = false;
      scene.add(mesh);
      this.rings.push({
        mesh, active: false, age: 0, life: 0.5,
        maxScale: 1, color: new THREE.Color(0x66ffff),
      });
    }

    // Shared geometry — dispose once at teardown (materials are per-ring clones).
    this._sharedGeo = geo;
  }

  /** Spawn a ring. `orient`: "floor" | "billboard". Returns the slot or null. */
  spawn(x, y, z, { color = 0x66ffff, maxScale = 1, life = 0.5, orient = 'floor' } = {}) {
    let slot = null;
    for (const r of this.rings) if (!r.active) { slot = r; break; }
    if (!slot) { // steal the oldest active ring when pool is exhausted
      let oldestAge = -1;
      for (const r of this.rings) if (r.age > oldestAge) { oldestAge = r.age; slot = r; }
    }

    const m = slot.mesh;
    slot.active = true;
    slot.age = 0;
    slot.life = life;
    slot.maxScale = maxScale;
    slot.color.setHex(color);
    m.material.emissive.copy(slot.color);
    m.position.set(x, y, z);
    if (orient === 'floor') {
      m.rotation.set(Math.PI / 2, 0, 0); // rotate the XY-plane torus flat onto XZ (faces up)
    } else {
      m.rotation.set(0, 0, 0); // billboard: default torus faces +Z — straight at the camera
    }
    m.scale.setScalar(0.05);
    m.visible = true;
    return slot;
  }

  update(dt) {
    for (const r of this.rings) {
      if (!r.active) continue;
      r.age += dt;
      const t = clamp(r.age / r.life, 0, 1);
      // Ease-out expansion.
      const e = 1 - Math.pow(1 - t, 2.4);
      const s = 0.05 + (r.maxScale - 0.05) * e;
      r.mesh.scale.setScalar(s);
      r.mesh.material.opacity = (1 - t) ** 1.6;
      if (t >= 1) {
        r.active = false;
        r.mesh.visible = false;
      }
    }
  }

  clear() { for (const r of this.rings) { r.active = false; r.mesh.visible = false; } }

  dispose() {
    for (const r of this.rings) {
      this.scene.remove(r.mesh);
      r.mesh.material.dispose(); // per-ring clones
    }
    this._sharedGeo.dispose();
  }
}

import { clamp } from '../utils/math.js';

/**
 * FloatingScoreText — pooled DOM score popups (glassmorphism chips) that track a
 * 3D anchor point, rise, and fade. One shared pool; no per-spawn allocation after warmup.
 */
export class FloatingScoreText {
  constructor(container, camera, { max = 14 } = {}) {
    this.container = container;
    this.camera = camera;
    this.max = max;

    // Preallocate the chip pool (DOM nodes are cheap to create once).
    this.chips = [];
    for (let i = 0; i < max; i++) {
      const el = document.createElement('div');
      el.className = 'score-chip';
      container.appendChild(el);
      this.chips.push({
        el, active: false, age: 0, life: 0.95,
        ax: 0, ay: 0, az: 0, // anchor in world space (fixed at spawn)
        rise: 0, opacity: 0, color: '#66ffff',
      });
    }

    this._v = { x: 0, y: 0, z: 0 }; // scratch for projection math below
  }

  /** Spawn a popup at world position. Returns the chip slot or null when pool exhausted. */
  spawn(x, y, z, text, color = '#66ffff') {
    let slot = this.chips.find((c) => !c.active);
    if (!slot) { // steal oldest active chip when exhausted
      let bestAge = -1;
      for (const c of this.chips) if (c.age > bestAge) { bestAge = c.age; slot = c; }
    }

    slot.active = true;
    slot.age = 0;
    slot.life = 0.95;
    slot.ax = x; slot.ay = y; slot.az = z;
    slot.rise = 0;
    slot.opacity = 1;
    slot.color = color;
    slot.el.textContent = text;
    slot.el.style.borderColor = color;
    slot.el.style.boxShadow = `0 0 18px ${color}55, inset 0 0 12px ${color}22`;
    slot.el.classList.remove('hidden');
    return slot;
  }

  update(dt) {
    const w = this.container.clientWidth || window.innerWidth;
    const h = this.container.clientHeight || window.innerHeight;
    for (const c of this.chips) {
      if (!c.active) continue;
      c.age += dt;
      const t = clamp(c.age / c.life, 0, 1);

      // Rise + fade-out.
      c.rise = 46 * (1 - Math.pow(1 - t, 2));
      c.opacity = t < 0.7 ? 1 : 1 - (t - 0.7) / 0.3;

      // Project world anchor → screen space.
      const v = this._v;
      v.x = c.ax; v.y = c.ay + c.rise * 0.02; v.z = c.az;
      const cam = this.camera.matrixWorldInverse.elements;
      // Manual projection (avoids importing THREE here): p' = P · V · w
      const inv = cam;
      const x1 = inv[0]*v.x + inv[4]*v.y + inv[8]*v.z + inv[12];
      const y1 = inv[1]*v.x + inv[5]*v.y + inv[9]*v.z + inv[13];
      const z1 = inv[2]*v.x + inv[6]*v.y + inv[10]*v.z + inv[14];
      if (z1 >= 0 || z1 <= -1e-6) { c.el.classList.add('hidden'); continue; } // behind camera
      const proj = this.camera.projectionMatrix.elements;
      const cx = (proj[0]*x1 + proj[4]*y1 + proj[8]*z1 + proj[12]) / -z1;
      const cy = (proj[1]*x1 + proj[5]*y1 + proj[9]*z1 + proj[13]) / -z1;
      if (!isFinite(cx) || !isFinite(cy)) { c.el.classList.add('hidden'); continue; }

      const sx = (cx * 0.5 + 0.5) * w;
      const sy = (-cy * 0.5 + 0.5) * h;
      c.el.style.transform = `translate(-50%, -100%) translate(${sx.toFixed(1)}px, ${sy.toFixed(1)}px)`;
      c.el.style.opacity = c.opacity.toFixed(3);

      if (t >= 1) {
        c.active = false;
        c.el.classList.add('hidden');
      }
    }
  }

  clear() { for (const c of this.chips) { c.active = false; c.el.classList.add('hidden'); } }

  dispose() {
    for (const c of this.chips) c.el.remove();
    this.chips.length = 0;
  }
}

/**
 * AudioEngine — 100% synthesized WebAudio (no asset files).
 * - Lazy AudioContext: created on first user gesture (browser autoplay policy).
 * - Master bus → DynamicsCompressor → destination.
 * - SFX bank built from oscillators + a shared white-noise buffer.
 * - "March" sequencer: the classic accelerating invader heartbeat, driven by
 *   Game via setAliveRatio() — tempo scales with remaining aliens.
 */

const NOTE_A = 196; // G3
const NOTE_B = 247; // B3

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this._noiseBuf = null;
    this._marchStep = 0;
    this._nextNoteTime = 0;
    this._aliveRatio = 1;
    this._ufoOsc = null;
    this._ufoLfo = null;
    this._unlocked = false;

    const unlock = () => this.unlock();
    window.addEventListener('pointerdown', unlock, { passive: true });
    window.addEventListener('keydown', unlock);
    this._unlockFns = [unlock];
  }

  /** Create the context + master bus. Safe to call repeatedly. */
  unlock() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return; // no audio support — every method below no-ops via null checks
    this.ctx = new AC();

    this.master = this.ctx.createGain();
    this.master.gain.value = 0.55;
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 24;
    comp.ratio.value = 6;
    this.master.connect(comp);
    comp.connect(this.ctx.destination);

    // Shared white-noise buffer (0.5 s) for explosions / impacts.
    const len = Math.floor(this.ctx.sampleRate * 0.5);
    this._noiseBuf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = this._noiseBuf.getChannelData(0);
